def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    # Fast access to opponent sequence
    opp = [h[1] for h in history]
    me = [h[0] for h in history]
    last_me, last_opp = history[-1]

    # Explicit last rounds: exploit/defect for final payoff, but avoid pointless mutual D.
    remaining = 100 - n
    if remaining <= 0:
        return 'D'
    if remaining == 1:
        # If opponent has been very cooperative, defect for 5.
        # If they are likely to defect anyway, defect is still usually better or equal.
        return 'D'
    if remaining <= 3:
        # In near-endgame, punish ongoing defections and take unilateral advantage if possible.
        if opp[-3:].count('D') >= 2:
            return 'D'
        if last_opp == 'C' and opp[-5:].count('C') >= 4:
            return 'D'
        return 'D' if last_opp == 'D' else 'C'

    # Detect persistent pure defection quickly.
    if n >= 6:
        if opp.count('C') == 0:
            # Give rare probes to re-establish cooperation, especially if mutual D is bad.
            if n % 11 == 0:
                return 'C'
            return 'D'

    # Detect near-pure cooperators and exploit only late/sparingly.
    opp_c = opp.count('C')
    if n >= 8:
        if opp_c == n:
            # Keep mutual cooperation normally. Defect only in a controlled spot near end.
            if n >= 90 and remaining > 3:
                return 'D' if n % 4 == 0 else 'C'
            return 'C'
        if opp_c >= n - 1 and n >= 12:
            # Very forgiving/nice opponent: cooperate, but occasionally test.
            if n >= 85:
                return 'D' if n % 3 == 0 else 'C'
            return 'C'

    # Opponent recent cooperation rates.
    w = 12 if n >= 12 else n
    recent_opp = opp[-w:]
    recent_opp_c = recent_opp.count('C')
    recent_rate = recent_opp_c / float(w)

    # Recent mutual cooperation state.
    recent_me = me[-w:]
    recent_me_c = recent_me.count('C')

    # If recent opponent cooperation is extremely low, defect mostly but probe occasionally.
    if recent_rate < 0.2:
        # If our defection is new and opponent just started defecting, retaliate clearly.
        if last_opp == 'D' and last_me == 'C':
            return 'D'
        # Rare probing to escape DD traps.
        if n % 13 == 0:
            return 'C'
        return 'D'

    # If opponent just defected after mutual cooperation, retaliate, but allow quick recovery.
    if last_opp == 'D':
        # Strong punishment if repeated recent defections.
        recent_defs = recent_opp.count('D')
        if recent_defs >= 3:
            # Avoid permanent DD: occasionally offer cooperation.
            if n % 9 == 0:
                return 'C'
            return 'D'
        # Single defection: retaliate once, then be ready to cooperate.
        if last_me == 'D':
            # We already retaliated last round. If they seem mostly cooperative, forgive now.
            if recent_rate >= 0.55:
                return 'C'
            return 'C' if rng.random() < 0.35 else 'D'
        return 'D'

    # Opponent just cooperated.
    if last_me == 'D':
        # If we were punishing and they cooperate, return to cooperation quickly.
        if recent_rate >= 0.45:
            return 'C'
        # If they are still rather defective overall, keep pressure but occasionally cooperate.
        return 'C' if rng.random() < 0.4 else 'D'

    # Default cooperative posture with careful anti-exploitation.
    if recent_rate >= 0.75:
        # Mostly cooperate. Rare controlled probes, but not too many.
        if n >= 20 and n % 17 == 0 and recent_opp_c < w:
            return 'D'
        return 'C'

    if recent_rate >= 0.45:
        # Mixed opponent: tit-for-tat with forgiveness.
        if last_opp == 'C':
            return 'C'
        return 'D'

    # Moderately defective opponent: defect more, but keep some recovery chance.
    if n % 7 == 0:
        return 'C'
    return 'D'
